 // API-001: Retrieve All Posts

 // Test 1: Verify HTTP status code
 pm.test("Status code is 200", function () {
     pm.response.to.have.status(200);
 });

 // Test 2: Verify response contains 100 posts
 pm.test("Response contains 100 posts", function () {
     const posts = pm.response.json();
     pm.expect(posts).to.be.an("array");
     pm.expect(posts.length).to.eql(100);
 });

 // Test 3: Verify posts contain required fields
 pm.test("Posts contain required fields", function () {
     const posts = pm.response.json();

     posts.forEach((post) => {
         pm.expect(post).to.have.all.keys(
             "userId",
             "id",
             "title",
             "body"
         );
     });
 });

 // API-002: Retrieve a Single Post

 // Test 1: Verify HTTP status code
 pm.test("Status code is 200", function () {
     pm.response.to.have.status(200);
 });

 // Test 2: Verify correct post is returned
 pm.test("Post ID is 1", function () {
     const post = pm.response.json();
     pm.expect(post.id).to.eql(1);
 });

 // Test 3: Verify required fields and data types
 pm.test("Post contains valid fields", function () {
     const post = pm.response.json();

     pm.expect(post.userId).to.be.a("number");
     pm.expect(post.id).to.be.a("number");
     pm.expect(post.title).to.be.a("string").and.not.empty;
     pm.expect(post.body).to.be.a("string").and.not.empty;
 });

 // API-003: Retrieve Nonexistent Post

 // Test 1: Verify HTTP status code
 pm.test("Status code is 404", function () {
     pm.response.to.have.status(404);
 });

 // Test 2: Verify empty JSON response
 pm.test("Response body is empty object", function () {
     const response = pm.response.json();

     pm.expect(response).to.be.an("object");
     pm.expect(response).to.be.empty;
 });

 // API-004: Filter Posts by User ID

 // Test 1: Verify HTTP status
 pm.test("Status code is 200", function () {
     pm.response.to.have.status(200);
 });

 // Test 2: Verify 10 posts are returned
 pm.test("Response contains 10 posts", function () {
     const posts = pm.response.json();

     pm.expect(posts).to.be.an("array");
     pm.expect(posts.length).to.eql(10);
 });

 // Test 3: Verify every post belongs to user 1
 pm.test("All posts belong to user ID 1", function () {
     const posts = pm.response.json();

     posts.forEach((post) => {
         pm.expect(post.userId).to.eql(1);
     });
 });

// API-005: Create a New Post

// Test 1: Verify HTTP status
pm.test("Status code is 201", function () {
    pm.response.to.have.status(201);
});

// Test 2: Verify the returned data
pm.test("Created post matches request data", function () {
    const post = pm.response.json();

    pm.expect(post.title).to.eql("API Testing Portfolio");
    pm.expect(post.body).to.eql("Testing POST requests using Postman");
    pm.expect(post.userId).to.eql(1);
});

// Test 3: Verify an ID is returned
pm.test("Created post has an ID", function () {
    const post = pm.response.json();

    pm.expect(post.id).to.be.a("number");
});

